/**
 * useWebUpdateCheck — polls /version.json every 5 minutes and compares the
 * build ID against the one baked into this loaded bundle. A mismatch means
 * a new deploy was pushed to the server. Returns { hasUpdate, buildId }.
 *
 * The build ID is injected at build time via Vite's `define` config:
 *   __WEB_BUILD_ID__ = "<git-sha-short>"
 *
 * version.json is generated by scripts/generate-version.mjs before each
 * `vite build` and served as a static file from public/.
 *
 * Cache-busting query param ensures the CDN doesn't serve a stale copy.
 */
/* global __WEB_BUILD_ID__, __WEB_PUSH_COUNT__ */
import { useState, useEffect, useRef } from 'react';
import { BUILD_NUMBER } from '@/changeLog';
import { WEB_VERSION } from '@/version';
import { base44 } from '@/api/base44Client';
import { isUpdateSuppressed, clearUpdateAttempts } from '@/components/utils/updateLoopGuard';

const POLL_INTERVAL = 5 * 60 * 1000; // 5 minutes

// Fallback if the define didn't run (dev mode, etc.)
const BUILT_BUILD_ID = typeof __WEB_BUILD_ID__ !== 'undefined' ? __WEB_BUILD_ID__ : 'dev';
// The push this bundle was built from (git commit count at build time).
const BUILT_PUSH_COUNT = typeof __WEB_PUSH_COUNT__ !== 'undefined' ? Number(__WEB_PUSH_COUNT__) || 0 : 0;

/**
 * Is the server build newer than the build this device is running?
 *
 * OWNER REPORT (Nov 2 2026): drivers on the LIVE site never saw the update
 * balloon — only a manual refresh got them the new code — while preview
 * worked. Two reasons:
 *   1. the whole check was string-only (server buildId vs the baked define)
 *      and the guard `BUILT_BUILD_ID !== 'dev'` DISABLED it completely on any
 *      bundle whose build id was missing at deploy time;
 *   2. /version.json is served with max-age=3600, so a plain fetch could come
 *      back as the device's own old copy.
 * The comparison is now numeric (BUILD_NUMBER + WEB_VERSION are real imports,
 * always present) with the id string kept only as an extra hint, and the
 * published build is fetched through the backend function as a fallback so a
 * CDN cache or a blocked fetch can no longer hide a publish.
 */
const parseBuildNumbers = (id) => {
  const m = /^b(\d+)\.w(\d+)/.exec(String(id || ''));
  if (!m) return null;
  return { buildNumber: Number(m[1]), webVersion: Number(m[2]) };
};

/**
 * Is the server build newer than the build this device is running?
 *
 * OWNER REPORT (Nov 5 2026): after installing APK v2.18.0 the app claimed a
 * "new version is ready" on every launch, and reloading or restarting never
 * cleared it.
 *
 * Cause: the comparison used WEB_VERSION as a tie-breaker whenever the build
 * numbers matched. WEB_VERSION is NOT monotonic — the owner rule resets it to 0
 * on every successful APK build. An APK baked at 0 therefore sits under a
 * still-warm /version.json reporting an older publish's digit (212), so
 * "212 > 0" read as "server is newer" forever, and every reload landed on the
 * very bundle that had just been declared newer.
 *
 * BUILD_NUMBER is the only monotonically increasing counter in the scheme, so
 * it alone decides now. Equal build numbers means current, no matter what the
 * resettable web digit says.
 */
const serverIsNewer = (server) => {
  if (!server) return false;
  // OWNER REPORT again (Nov 5 2026): "no update notifications for the last two
  // fixes" — the immersive-panel push (w5) and the header-icon push (w6). A web
  // push bumps only WEB_VERSION, and WEB_VERSION cannot be trusted for this
  // comparison (the APK build resets it to 0, which produced the endless
  // "update available" loop fixed above). BUILD_NUMBER only moves on APK
  // releases. So neither counter moved, and no device was ever told.
  //
  // The git commit count is monotonic and travels in version.json. When BOTH
  // sides carry it, it alone decides — any push, web-only included, is newer.
  const serverPushes = Number(server.pushCount);
  if (BUILT_PUSH_COUNT > 0 && Number.isFinite(serverPushes) && serverPushes > 0) {
    return serverPushes > BUILT_PUSH_COUNT;
  }
  // Older deploys (or a bundle built without git) fall back to BUILD_NUMBER.
  const sBn = Number(server.buildNumber);
  if (!Number.isFinite(sBn)) return false;
  return sBn > BUILD_NUMBER;
};

export function useWebUpdateCheck() {
  const [hasUpdate, setHasUpdate] = useState(false);
  const [currentBuildId, setCurrentBuildId] = useState(null);
  const [suppressedBuildId, setSuppressedBuildId] = useState(null);
  const mountedRef = useRef(true);

  useEffect(() => {
    mountedRef.current = true;
    let timer = null;
    let cancelled = false;

    const check = async () => {
      try {
        const resp = await fetch(`/version.json?cb=${Date.now()}`, {
          cache: 'no-store',
          headers: { 'Cache-Control': 'no-cache' },
        });
        if (!resp.ok) return;
        const data = await resp.json();
        if (cancelled || !mountedRef.current) return;

        const serverBuildId = data?.buildId;
        if (!serverBuildId) return;

        setCurrentBuildId(serverBuildId);

        const parsed = parseBuildNumbers(serverBuildId);
        const server = {
          buildId: serverBuildId,
          buildNumber: data?.buildNumber ?? parsed?.buildNumber,
          webVersion: data?.webVersion ?? parsed?.webVersion,
          pushCount: data?.pushCount ?? null,
        };
        // ID strings are NO LONGER part of the decision (owner report Nov 4
        // 2026). They made a device whose reload kept landing on a cached
        // index.html report "update available" forever. Only the version
        // numbers count, and a build the device already failed to reach is
        // suppressed instead of nagging.
        if (serverIsNewer(server)) {
          if (isUpdateSuppressed(serverBuildId)) {
            setHasUpdate(false);
            setSuppressedBuildId(serverBuildId);
            console.warn('[Update] suppressed — reload never reached', serverBuildId);
            return;
          }
          setHasUpdate(true);
          return;
        }
        // Numbers are equal: we are current. If an earlier reload finally
        // landed, clear the attempt history so future updates prompt normally.
        clearUpdateAttempts();
        setHasUpdate(false);
        // The relative fetch may be the device's own cached copy — confirm the
        // published build once through the backend.
        await checkViaBackend();
      } catch {
        // Direct fetch failed (CORS, CDN oddity, offline). Fall back to the
        // backend lookup of the LIVE published build before giving up.
        await checkViaBackend();
      }
    };

    const checkViaBackend = async () => {
      try {
        const res = await base44.functions.invoke('getPublishedBuildInfo', {});
        const data = res?.data || res;
        if (cancelled || !mountedRef.current) return;
        if (!data?.buildNumber) return;
        setCurrentBuildId(data.buildId || null);
        const server = { buildId: data.buildId, buildNumber: data.buildNumber, webVersion: data.webVersion, pushCount: data.pushCount ?? null };
        if (serverIsNewer(server)) {
          if (isUpdateSuppressed(data.buildId)) {
            setHasUpdate(false);
            setSuppressedBuildId(data.buildId || null);
            return;
          }
          setHasUpdate(true);
        }
      } catch {
        // silent — no badge
      }
    };

    // Delay first check 10s after mount to avoid competing with boot
    const delayTimer = setTimeout(() => {
      check();
      timer = setInterval(check, POLL_INTERVAL);
    }, 10_000);

    return () => {
      cancelled = true;
      mountedRef.current = false;
      clearTimeout(delayTimer);
      if (timer) clearInterval(timer);
    };
  }, []);

  return { hasUpdate, currentBuildId, suppressedBuildId, builtBuildId: BUILT_BUILD_ID };
}